import { useEffect, useState } from "react";

type Repo = { id: number; full_name: string; stargazers_count: number };

export function RepoSearch({ query }: { query: string }) {
  const [repos, setRepos] = useState<Repo[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!query) return;
    const controller = new AbortController();
    setLoading(true);
    setError(null);
    fetch(`https://api.github.com/search/repositories?q=${encodeURIComponent(query)}`,
          { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`GitHub returned ${res.status}`);
        return res.json();
      })
      .then((body) => setRepos(body.items))
      .catch((err) => { if (err.name !== "AbortError") setError(err.message); })
      .finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [query]);

  if (error) return <p role="alert">{error}</p>;
  if (loading) return <p>Loading…</p>;
  return <ul>{repos.map((r) => <li key={r.id}>{r.full_name} ★{r.stargazers_count}</li>)}</ul>;
}

// src/features/search/useRepos.ts
import { useEffect, useState } from "react";
import { searchRepos, type Repo } from "./api";

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ok"; repos: Repo[] };

export function useRepos(query: string): State {
  const [state, setState] = useState<State>({ status: "idle" });

  useEffect(() => {
    if (!query) { setState({ status: "idle" }); return; }
    const controller = new AbortController();
    setState({ status: "loading" });
    searchRepos(query, controller.signal)
      .then((repos) => setState({ status: "ok", repos }))
      .catch((err) => {
        if (err.name !== "AbortError") setState({ status: "error", message: err.message });
      });
    return () => controller.abort();
  }, [query]);

  return state;
}

